// la página de una película: directa y, si no trae horas, renderizada
const horas = (t) => (String(t).match(/\b\d{1,2}:\d{2}\b/g) || []).length;
const diaTxt = (f) => f.slice(8, 10) + '/' + f.slice(5, 7);
const leerPelicula = async (c, url) => {
  try {
    let navd = null;
    if (!nav.caido) {
      const nd = await navDia(url, v.fecha);
      if (nd && nd.html) {
        const esHoy = v.fecha === v.hoy;
        const diaOk = esHoy || nd.clic || nd.yaActivo;
        const hz = horariosGenerico(nd.html, url, { hoy: v.hoy });
        const otroDia = hz.diaActivo && hz.diaActivo !== v.fecha;
        navd = { clic: !!nd.clic, etiqueta: nd.etiquetaClic || '', yaActivo: !!nd.yaActivo, error: nd.error || '', sedes: hz.sedes.length };
        if (diaOk && !otroDia && hz.sedes.length) {
          const sedes = hz.sedes.map(s => ({ sede: s.sede || c.nombre, horarios: s.horarios.map(h => ({ hora: h.hora, formato: h.formato || '', idioma: h.idioma || '' })) }));
          return { c, d: { id: c.id, leida: true, http: 200, error: '', via: 'navegador', causa: 'ok', navegador: navd }, texto: '', det: { sedes, nota: 'Leído con navegador para el ' + diaTxt(v.fecha) } };
        }
        if (diaOk && !otroDia && hz.sinFunciones) return { c, d: { id: c.id, leida: true, http: 200, error: '', via: 'navegador', causa: 'ok', navegador: navd }, texto: '', det: { sedes: [], nota: 'Sin funciones el ' + diaTxt(v.fecha) } };
        if (diaOk && !otroDia) { const tx = compacto(nd.html, url); if (horas(tx) >= 1) return { c, d: { id: c.id, leida: true, http: 200, error: '', via: 'navegador', causa: 'ok', navegador: navd }, texto: tx }; }
        navd.nota = diaOk ? (otroDia ? 'dia_distinto' : 'sin_horas') : 'no_cambio_de_dia';
      } else if (nd) navd = { error: nd.error || 'sin_html' };
    }
    const r = await traer([url], false);
    let texto = r.texto, via = r.via, causa = r.causa;
    if (horas(texto) < 3 && r.via !== 'jina') { const r2 = await traer([url], true); if (r2.texto && horas(r2.texto) >= horas(texto)) { texto = r2.texto; via = 'jina'; causa = r2.causa; } }
    return { c, d: { id: c.id, leida: !!texto, http: r.status, error: r.err, via, causa, navegador: navd || (nav.error || 'no_usado') }, texto };
  } catch (e) { return { c, d: { id: c.id, leida: false, http: 0, error: String(e.message || e).slice(0, 120), via: 'ninguna', causa: 'error_interno' }, texto: '' }; }
};

if (v.accion === 'cartelera') {
  const leidos = await Promise.all(CINES.map(leerCine));
  sd.diagClave = v.clave;
  sd.diag = leidos.map(x => x.d);
  const secc = leidos.map(x => {
    if (x.cand.length >= 3) return '=== ' + x.c.id + ' · ' + x.c.nombre + ' · CANDIDATOS (T título | I póster | U enlace) ===\n' + x.cand.map(k => 'T: ' + k.t + ' | I: ' + k.i + ' | U: ' + k.u).join('\n');
    if (x.texto) return '=== ' + x.c.id + ' · ' + x.c.nombre + ' · TEXTO DE LA PÁGINA ===\n' + x.texto;
    return '';
  }).filter(Boolean).join('\n\n');
  const prompt = secc
    ? 'Esto salió de las páginas de cartelera de cines de Cali, Colombia. Para los cines con CANDIDATOS (título | póster | enlace) quita lo que no sea una película en cartelera (promociones, combos, sedes, menús, ciudades) y deja el título limpio (sin «2D», «3D», «Doblada», «Subtitulada»); no cambies el póster ni el enlace. Para los cines con TEXTO DE LA PÁGINA ([IMG url] imagen, [A url] enlace) saca tú las películas: titulo, poster (la imagen del póster de esa película, la que acompaña al título; null si no hay) y url (enlace de la película; null si no hay). Si un cine no trae películas, deja su lista vacía. Formato: {"cines":[{"id":"cc","peliculas":[{"titulo":"","poster":null,"url":null}]},{"id":"cp","peliculas":[]},{"id":"cm","peliculas":[]}]}\n\n' + secc
    : 'Responde exactamente {"cines":[]}';
  const peticion = { model: MODELO, max_tokens: secc ? 8000 : 50, system: 'Eres un extractor de datos. Responde SOLO con JSON válido, sin texto adicional. No inventes nada: usa solo lo que aparece en el texto.', messages: [{ role: 'user', content: prompt }] };
  return [{ json: Object.assign({}, v, { peticion }) }];
}

// horarios: la página de la película en cada cine donde está en cartelera
const ids = CINES.filter(c => v.urls && v.urls[c.id]);
const leidos = await Promise.all(ids.map(c => leerPelicula(c, v.urls[c.id])));
sd.diagH = leidos.map(x => x.d);
const det = {}; leidos.forEach(x => { if (x.det) det[x.c.id] = x.det; });
const secc = leidos.filter(x => x.texto && !x.det).map(x => '=== ' + x.c.id + ' · ' + x.c.nombre + ' ===\n' + x.texto).join('\n\n');
const prompt = secc
  ? 'Estas son páginas de la película «' + v.titulo + '» en cines de Cali, Colombia (texto simplificado). Saca las funciones de Cali SOLO para el día ' + v.fecha + '. La página muestra por defecto el día de hoy (' + v.hoy + '): si el día pedido no es hoy y la página no trae las horas de ese día, deja las sedes vacías y explícalo en «nota». No mezcles horarios de otros días. Para cada cine lista sus sedes de Cali y los horarios (hora en 24h «HH:MM», formato 2D/3D/4DX/VIP y idioma Doblada/Subtitulada). Solo lo que aparece en el texto; si no ves horarios, deja sedes vacías. Formato: {"cines":[{"id":"cc","sedes":[{"sede":"","horarios":[{"hora":"18:30","formato":"2D","idioma":"Subtitulada"}]}],"nota":""}]}\n\n' + secc
  : 'Responde exactamente {"cines":[]}';
const peticion = { model: MODELO, max_tokens: secc ? 4000 : 50, system: 'Eres un extractor de datos. Responde SOLO con JSON válido, sin texto adicional. No inventes nada: usa solo lo que aparece en el texto.', messages: [{ role: 'user', content: prompt }] };
return [{ json: Object.assign({}, v, { peticion, det }) }];
